<script lang="ts" module>import type { Snippet } from 'svelte'; import type { RxColor } from '$lib/registry/lib/color'; export interface TimelineItem {id?:string;title:string;description?:string|Snippet;time?:string;icon?:Snippet;color?:RxColor} export interface TimelineProps {items:TimelineItem[];color?:RxColor;variant?:'default'|'alternating'|'cards'|'compact'|'glow'|'gradient';orientation?:'vertical'|'horizontal'}</script>
<script lang="ts">import { styleColor } from '$lib/registry/lib/color'; let {items,color,variant='default',orientation='vertical'}:TimelineProps=$props();</script>
<ol class="rx-timeline rx-timeline--{variant} rx-timeline--{orientation}" style={styleColor(color) ?? '--rx-color: var(--rx-primary)'}>
 {#each items as item (item.id ?? item.title)}<li style={styleColor(item.color)}><span class="rx-timeline__dot" aria-hidden="true">{#if item.icon}{@render item.icon()}{/if}</span><article><header><strong>{item.title}</strong>{#if item.time}<time>{item.time}</time>{/if}</header>{#if typeof item.description==='string'}<p>{item.description}</p>{:else if item.description}{@render item.description()}{/if}</article></li>{/each}
</ol>
<style>.rx-timeline{position:relative;display:grid;list-style:none;margin:0;padding:0;gap:1.25rem}.rx-timeline::before{content:'';position:absolute;background:rgb(var(--rx-color)/.25)}.rx-timeline--vertical::before{left:.7rem;top:.7rem;bottom:.7rem;width:2px}.rx-timeline li{position:relative;display:grid;grid-template-columns:1.5rem 1fr;gap:.8rem}.rx-timeline__dot{z-index:1;display:grid;place-items:center;width:1.45rem;height:1.45rem;border-radius:999px;background:rgb(var(--rx-color));color:rgb(var(--rx-light));font-size:.7rem}.rx-timeline article{padding:.1rem 0}.rx-timeline header{display:flex;justify-content:space-between;gap:1rem}.rx-timeline time,.rx-timeline p{opacity:.65;font-size:.82rem}.rx-timeline p{margin:.35rem 0 0}.rx-timeline--cards article{padding:1rem;border-radius:var(--rx-radius);background:rgb(var(--rx-surface));box-shadow:var(--rx-shadow)}.rx-timeline--compact{gap:.55rem}.rx-timeline--glow .rx-timeline__dot{box-shadow:0 0 1.1rem rgb(var(--rx-color)/.7)}.rx-timeline--gradient::before{background:linear-gradient(rgb(var(--rx-color)),hsl(from rgb(var(--rx-color)) calc(h + 35) s l))}.rx-timeline--horizontal{grid-auto-flow:column;grid-auto-columns:minmax(10rem,1fr)}.rx-timeline--horizontal::before{left:.7rem;right:.7rem;top:.7rem;height:2px}.rx-timeline--horizontal li{grid-template-columns:1fr;grid-template-rows:1.5rem auto}.rx-timeline--alternating li:nth-child(even){margin-left:50%}.rx-timeline--alternating li:nth-child(odd){margin-right:50%}@media(max-width:640px){.rx-timeline--alternating li{margin-left:0!important;margin-right:0!important}}@media(prefers-reduced-motion:reduce){.rx-timeline__dot{animation:none!important;transition:none!important}}</style>
